def oexcl(path:Path, data:bytes):
    if path.exists(): raise SystemExit(f'exists {path}')
    fd=os.open(str(path), os.O_CREAT|os.O_EXCL|os.O_WRONLY)
    try: os.write(fd,data)
    except Exception:
        os.close(fd)
        if path.exists(): path.unlink()
        raise
    else: os.close(fd)

